    "contracts/ConfigProposal.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IBaalV3} from "./Interfaces.sol";
import {ProposalBase} from "./ProposalBase.sol";

/// @notice Config template (DESIGN.md §7.5): change Baal's governance parameters by proposal.
/// @dev Baal.setGovernanceConfig is callable only by the Safe (avatar) or a governor shaman, so the
/// voted multicall is [Baal.setGovernanceConfig(governanceConfig()), start()] executed by the Safe;
/// start() then reads every parameter back and reverts unless Baal holds exactly the voted values,
/// which fails the whole action atomically. No settlement is involved; budget = 0.
/// params = abi.encode(Config). No operational role for the proposer.
contract ConfigProposal is ProposalBase {
    struct Config {
        uint32 votingPeriod;
        uint32 gracePeriod;
        uint256 proposalOffering;
        uint256 quorumPercent;
        uint256 sponsorThreshold;
        uint256 minRetentionPercent;
    }

    IBaalV3 public immutable baal;
    Config public config;

    error NotApplied(string parameter);
    error NotApplicable();

    /// @param safe_ The treasury Safe.
    /// @param settlement_ The settlement ERC-20 (unused; kept for the common surface).
    /// @param operator_ The proposer (recorded; no role).
    /// @param baal_ The Baal whose parameters change.
    /// @param config_ The voted governance parameters.
    constructor(address safe_, address settlement_, address operator_, IBaalV3 baal_, Config memory config_)
        ProposalBase(safe_, settlement_, operator_)
    {
        if (address(baal_) == address(0)) revert ZeroAddress();
        baal = baal_;
        _set(config_);
    }

    /// @inheritdoc ProposalBase
    function template() public pure override returns (string memory) {
        return "Config";
    }

    /// @notice The exact bytes for Baal.setGovernanceConfig.
    function governanceConfig() public view returns (bytes memory) {
        Config memory c = config;
        return abi.encode(c.votingPeriod, c.gracePeriod, c.proposalOffering, c.quorumPercent, c.sponsorThreshold, c.minRetentionPercent);
    }

    /// @dev Verify Baal now holds the voted values; ends Complete.
    function _start() internal override {
        Config memory c = config;
        if (baal.votingPeriod() != c.votingPeriod) revert NotApplied("votingPeriod");
        if (baal.gracePeriod() != c.gracePeriod) revert NotApplied("gracePeriod");
        if (baal.proposalOffering() != c.proposalOffering) revert NotApplied("proposalOffering");
        if (baal.quorumPercent() != c.quorumPercent) revert NotApplied("quorumPercent");
        if (baal.sponsorThreshold() != c.sponsorThreshold) revert NotApplied("sponsorThreshold");
        if (baal.minRetentionPercent() != c.minRetentionPercent) revert NotApplied("minRetentionPercent");
        _complete();
    }

    /// @dev No money in a Config proposal.
    function _topUp(uint256) internal pure override {
        revert NotApplicable();
    }

    /// @dev Replace the parameters before start.
    function _amend(bytes calldata params) internal override {
        _requireStatus(Status.Pending);
        _set(abi.decode(params, (Config)));
    }

    function _set(Config memory config_) private {
        config = config_;
        paramsHash = keccak256(abi.encode(config_));
    }
}
"
    },
    "contracts/Interfaces.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC20Minimal {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IERC20Metadata is IERC20Minimal {
    function decimals() external view returns (uint8);
}

/// @notice Zero One share token surface used by the shamans.
interface INavShareToken is IERC20Minimal {
    function baal() external view returns (address);
    function safe() external view returns (address);
    function settlementToken() external view returns (address);
    function treasuryValue() external view returns (uint256);
    function navSharesFor(uint256 contributedValue) external view returns (uint256);
    function navValueForShares(uint256 shares) external view returns (uint256);
    function getVotes(address account) external view returns (uint256);
    function getPastVotes(address account, uint256 timePoint) external view returns (uint256);
}

/// @notice Narrow ABI of audited @daohaus/baal-contracts 1.2.18 used by Zero One.
interface IBaalV3 {
    function avatar() external view returns (address);
    function target() external view returns (address);
    function sharesToken() external view returns (address);
    function lootToken() external view returns (address);
    function shamans(address shaman) external view returns (uint256);
    function isManager(address shaman) external view returns (bool);
    function votingPeriod() external view returns (uint32);
    function gracePeriod() external view returns (uint32);
    function sponsorThreshold() external view returns (uint256);
    function proposalOffering() external view returns (uint256);
    function quorumPercent() external view returns (uint256);
    function minRetentionPercent() external view returns (uint256);
    function totalShares() external view returns (uint256);

    function mintShares(address[] calldata to, uint256[] calldata amount) external;
    function burnShares(address[] calldata from, uint256[] calldata amount) external;
    function setShamans(address[] calldata shamans_, uint256[] calldata permissions) external;
    function setGovernanceConfig(bytes calldata governanceConfig) external;

    function encodeMultisend(bytes[] calldata calls, address target) external pure returns (bytes memory);
    function submitProposal(
        bytes calldata proposalData,
        uint32 expiration,
        uint256 baalGas,
        string calldata details
    ) external payable returns (uint256);
    function sponsorProposal(uint32 id) external;
    function submitVote(uint32 id, bool approved) external;
    function processProposal(uint32 id, bytes calldata proposalData) external;
    function cancelProposal(uint32 id) external;
    function ragequit(address to, uint256 sharesToBurn, uint256 lootToBurn, address[] calldata tokens) external;
    function state(uint32 id) external view returns (uint8);
}

interface IDepositShaman {
    function deposit(uint256 amount) external returns (uint256 sharesMinted);
    function settlementToken() external view returns (address);
}

interface IWorkManager {
    function submitTask(
        address[] calldata verifiers,
        uint16 verifierThreshold,
        uint256 rewardShares,
        uint32 expiration,
        string calldata details
    ) external payable returns (uint256 taskId, uint256 proposalId);
    function claim(uint256 taskId) external;
    function deliver(uint256 taskId, bytes32 evidenceHash) external;
    function confirm(uint256 taskId, bytes calldata evidence) external;
}
"
