    "contracts/ProposalBase.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20Minimal} from "./Interfaces.sol";
import {IProposalContract} from "./IProposalContract.sol";

/// @notice Shared skeleton of the proposal templates: Safe ownership, status, budget, settlement
/// accounting and the default stop / migrate behaviour (return or move the settlement balance).
/// @dev Templates override the `_start / _topUp / _amend / _stop / _migrate` hooks. Every external
/// state-changing entry point except the template's own operational functions is `onlySafe`, so
/// only a passed proposal (executed by the Safe through Baal) can call it (DESIGN.md §7).
abstract contract ProposalBase is IProposalContract {
    address public immutable safe;
    IERC20Minimal public immutable settlement;
    address public immutable operator;

    Status public status;
    uint256 public budget;
    uint256 public deadline;
    bytes32 public paramsHash;

    uint256 private _entered = 1;

    error Reentrancy();
    error ZeroAddress();
    error OnlySafe(address caller);
    error WrongStatus(Status observed);
    error TransferFailed();
    error Underfunded(uint256 required, uint256 held);
    error NotAContract(address target);

    event Started(uint256 budget);
    event ToppedUp(uint256 amount, uint256 budget);
    event Amended(bytes32 paramsHash);
    event Stopped(uint256 returned);
    event Migrated(address indexed newContract, uint256 moved);
    event Completed(uint256 returned);

    modifier nonReentrant() {
        if (_entered != 1) revert Reentrancy();
        _entered = 2;
        _;
        _entered = 1;
    }

    modifier onlySafe() {
        if (msg.sender != safe) revert OnlySafe(msg.sender);
        _;
    }

    /// @param safe_ The treasury Safe (owner of every proposal contract).
    /// @param settlement_ The settlement ERC-20 (USDC).
    /// @param operator_ The address that leads execution (the proposer by default).
    constructor(address safe_, address settlement_, address operator_) {
        if (safe_ == address(0) || settlement_ == address(0) || operator_ == address(0)) revert ZeroAddress();
        safe = safe_;
        settlement = IERC20Minimal(settlement_);
        operator = operator_;
    }

    /// @notice Template name; overridden by each template.
    function template() public pure virtual returns (string memory);

    /// @inheritdoc IProposalContract
    function describe()
        external
        view
        returns (string memory template_, bytes32 paramsHash_, address operator_, uint256 budget_, uint256 deadline_, Status status_)
    {
        return (template(), paramsHash, operator, budget, deadline, status);
    }

    /// @inheritdoc IProposalContract
    function start() external onlySafe nonReentrant {
        _requireStatus(Status.Pending);
        status = Status.Running;
        _start();
        emit Started(budget);
    }

    /// @inheritdoc IProposalContract
    function topUp(uint256 amount) external onlySafe nonReentrant {
        _requireLive();
        _topUp(amount);
        emit ToppedUp(amount, budget);
    }

    /// @inheritdoc IProposalContract
    function amend(bytes calldata params) external onlySafe nonReentrant {
        _requireLive();
        _amend(params);
        emit Amended(paramsHash);
    }

    /// @inheritdoc IProposalContract
    function stop() external onlySafe nonReentrant {
        _requireLive();
        status = Status.Stopped;
        uint256 returned = _stop();
        emit Stopped(returned);
    }

    /// @inheritdoc IProposalContract
    function migrate(address newContract) external onlySafe nonReentrant {
        _requireLive();
        if (newContract == address(0)) revert ZeroAddress();
        if (newContract.code.length == 0) revert NotAContract(newContract);
        status = Status.Migrated;
        uint256 moved = _migrate(newContract);
        emit Migrated(newContract, moved);
    }

    /// @notice Settlement currently held by this contract.
    function held() public view returns (uint256) {
        return settlement.balanceOf(address(this));
    }

    /// @dev Template hook: called once when the Safe starts the contract (status already Running).
    function _start() internal virtual;

    /// @dev Template hook: the Safe has transferred `amount` more settlement; default records it.
    function _topUp(uint256 amount) internal virtual {
        budget += amount;
    }

    /// @dev Template hook: replace parameters with the voted `params` and update `paramsHash`.
    function _amend(bytes calldata params) internal virtual;

    /// @dev Template hook: return everything to the Safe (status already Stopped); default returns settlement.
    function _stop() internal virtual returns (uint256 returned) {
        return _returnSettlement(safe);
    }

    /// @dev Template hook: move everything to `newContract` (status already Migrated); default moves settlement.
    function _migrate(address newContract) internal virtual returns (uint256 moved) {
        return _returnSettlement(newContract);
    }

    /// @dev Mark Complete and return whatever settlement is left to the Safe.
    function _complete() internal {
        status = Status.Complete;
        uint256 returned = _returnSettlement(safe);
        emit Completed(returned);
    }

    /// @dev Transfer the whole settlement balance to `to`; returns the amount moved.
    function _returnSettlement(address to) internal returns (uint256 amount) {
        amount = settlement.balanceOf(address(this));
        if (amount != 0) _transfer(to, amount);
    }

    /// @dev ERC-20 transfer that reverts on a false return.
    function _transfer(address to, uint256 amount) internal {
        if (!settlement.transfer(to, amount)) revert TransferFailed();
    }

    /// @dev Revert unless `status == expected`.
    function _requireStatus(Status expected) internal view {
        if (status != expected) revert WrongStatus(status);
    }

    /// @dev Revert unless the contract is Pending or Running (i.e. can still be governed).
    function _requireLive() internal view {
        if (status != Status.Pending && status != Status.Running) revert WrongStatus(status);
    }
}
"
    },
    "contracts/IProposalContract.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The common surface of every Zero One proposal contract (DESIGN.md §7).
/// @dev A proposal contract is deployed by the proposer, funded and started by the Safe when the Baal
/// proposal passes (the voted multicall is `settlement.transfer(instance, budget)` + `start()`), and
/// owned by the Safe afterwards: topUp / amend / stop / migrate are callable only by the Safe, i.e.
/// only by a later passed proposal. The proposer holds only the operational role its template defines.
interface IProposalContract {
    /// @notice Lifecycle of a proposal contract.
    /// Pending: deployed, not yet started (a failed vote leaves it here forever, holding nothing).
    /// Running: funded and started. Complete: finished by its own rules; everything returned to the Safe.
    /// Stopped: stopped by a passed proposal; everything returned to the Safe.
    /// Migrated: funds moved to a new voted contract by a passed proposal.
    enum Status {
        Pending,
        Running,
        Complete,
        Stopped,
        Migrated
    }

    /// @notice Template name, hash of the voted parameters, operator, budget, deadline and status.
    /// @return template Template name ("Payment", "Strategy", "Project", "Config").
    /// @return paramsHash keccak256(abi.encode(params)) of the latest voted parameters.
    /// @return operator The address that leads execution (the proposer by default).
    /// @return budget Settlement units the treasury has committed to this contract (funding + topUps).
    /// @return deadline Unix time after which the contract ends by itself (0 = none).
    /// @return status Current lifecycle status.
    function describe()
        external
        view
        returns (string memory template, bytes32 paramsHash, address operator, uint256 budget, uint256 deadline, Status status);

    /// @notice Executed by the Safe in the voted multicall right after funding.
    function start() external;

    /// @notice Executed by the Safe (a later passed proposal) after transferring `amount` more settlement.
    function topUp(uint256 amount) external;

    /// @notice Executed by the Safe (a later passed proposal): replace the template's parameters.
    function amend(bytes calldata params) external;

    /// @notice Executed by the Safe (a later passed proposal): return everything to the Safe and end.
    function stop() external;

    /// @notice Executed by the Safe (a later passed proposal): move everything to `newContract`.
    function migrate(address newContract) external;
}
"
    },
    "contracts/Constitution.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The constitution of Zero One as an on-chain constant: the keccak256 of the exact bytes of
/// docs/CONSTITUTION.md and a URL where that text can be read. Set once at construction; there is
/// no setter, no owner and no amendment path (DESIGN.md §10, constitution Art. VII).
/// @dev `textUrl` is a string and Solidity cannot mark strings immutable; it is written once in the
/// constructor and no function in this contract writes storage afterwards, so it is immutable in fact.
contract Constitution {
    /// @notice keccak256 over the exact bytes of docs/CONSTITUTION.md.
    bytes32 public immutable textHash;
    /// @notice Where the text lives (documentation only; the hash is the authority).
    string public textUrl;

    error EmptyHash();
    error EmptyUrl();

    event ConstitutionAdopted(bytes32 indexed textHash, string textUrl);

    /// @param textHash_ keccak256 of the constitution text bytes.
    /// @param textUrl_ Location of the text (any non-empty string).
    constructor(bytes32 textHash_, string memory textUrl_) {
        if (textHash_ == bytes32(0)) revert EmptyHash();
        if (bytes(textUrl_).length == 0) revert EmptyUrl();
        textHash = textHash_;
        textUrl = textUrl_;
        emit ConstitutionAdopted(textHash_, textUrl_);
    }

    /// @notice True when `text` is byte-for-byte the adopted constitution.
    /// @param text Candidate text bytes.
    /// @return matches Whether keccak256(text) equals the adopted hash.
    function verify(bytes calldata text) external view returns (bool matches) {
        return keccak256(text) == textHash;
    }
}
"
    },
    "contracts/DepositShaman.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IBaalV3, IERC20Minimal, INavShareToken} from "./Interfaces.sol";

/// @notice Deposit the settlement asset (USDC, 6 dec) into the treasury Safe and receive shares.
/// @dev shares = amount x totalShares / treasury when treasury > 0; when treasury == 0, one share
/// per one settlement unit scaled to share decimals (1 USDC -> 1e18 shares). No other fallback
/// (NavShareToken.navSharesFor). Baal manager shaman. Open to any address: phase-1 "agents only" is
/// a constitution clause enforced by votes, not by code (DESIGN.md §2). Exit is Baal.ragequit at NAV.
contract DepositShaman {
    IBaalV3 public immutable baal;
    address public immutable safe;
    INavShareToken public immutable shares;
    IERC20Minimal public immutable settlementToken;

    uint256 private _entered = 1;

    error Reentrancy();
    error ZeroAddress();
    error ZeroAmount();
    error ZeroShares(uint256 amount);
    error TransferFailed();
    error InexactDeposit(uint256 expected, uint256 observed);

    event Deposited(
        address indexed depositor,
        uint256 amount,
        uint256 sharesMinted,
        uint256 treasuryValueBefore,
        uint256 supplyBefore
    );

    modifier nonReentrant() {
        if (_entered != 1) revert Reentrancy();
        _entered = 2;
        _;
        _entered = 1;
    }

    constructor(IBaalV3 baal_, INavShareToken shares_) {
        if (address(baal_) == address(0) || address(shares_) == address(0)) revert ZeroAddress();
        baal = baal_;
        shares = shares_;
        safe = shares_.safe();
        settlementToken = IERC20Minimal(shares_.settlementToken());
        if (safe == address(0) || address(settlementToken) == address(0)) revert ZeroAddress();
    }

    /// @notice Shares that `amount` of the settlement asset would mint right now.
    function quote(uint256 amount) external view returns (uint256) {
        return shares.navSharesFor(amount);
    }

    /// @notice Pull `amount` (pre-approved) from the caller into the Safe and mint shares at NAV.
    /// @return sharesMinted Shares credited to the caller.
    function deposit(uint256 amount) external nonReentrant returns (uint256 sharesMinted) {
        if (amount == 0) revert ZeroAmount();
        uint256 valueBefore = shares.treasuryValue();
        uint256 supplyBefore = shares.totalSupply();
        sharesMinted = shares.navSharesFor(amount);
        if (sharesMinted == 0) revert ZeroShares(amount);
        if (!settlementToken.transferFrom(msg.sender, safe, amount)) revert TransferFailed();
        uint256 valueAfter = shares.treasuryValue();
        if (valueAfter != valueBefore + amount) revert InexactDeposit(valueBefore + amount, valueAfter);
        address[] memory to = new address[](1);
        uint256[] memory amounts = new uint256[](1);
        to[0] = msg.sender;
        amounts[0] = sharesMinted;
        baal.mintShares(to, amounts);
        emit Deposited(msg.sender, amount, sharesMinted, valueBefore, supplyBefore);
    }
}
"
    },
    "contracts/LootToken.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Minimal Baal loot token. Zero One mints no loot; Baal only requires the token to exist.
/// @dev Mint and burn are accepted only from the immutable Baal. Supply stays zero unless a passed
/// proposal installs a manager shaman that mints loot; nothing in code forbids that.
contract LootToken {
    string public name;
    string public symbol;
    uint8 public constant decimals = 18;

    address public immutable baal;
    uint256 public totalSupply;

    mapping(address account => uint256) public balanceOf;
    mapping(address owner => mapping(address spender => uint256)) public allowance;

    error OnlyBaal(address caller);
    error ZeroAddress();
    error PermanentlyUnpaused();
    error InsufficientBalance(address account, uint256 available, uint256 required);
    error InsufficientAllowance(address owner, address spender, uint256 available, uint256 required);

    event Transfer(address indexed from, address indexed to, uint256 amount);
    event Approval(address indexed owner, address indexed spender, uint256 amount);

    modifier onlyBaal() {
        if (msg.sender != baal) revert OnlyBaal(msg.sender);
        _;
    }

    constructor(string memory name_, string memory symbol_, address baal_) {
        if (baal_ == address(0)) revert ZeroAddress();
        name = name_;
        symbol = symbol_;
        baal = baal_;
    }

    function paused() external pure returns (bool) {
        return false;
    }

    function pause() external pure {
        revert PermanentlyUnpaused();
    }

    function unpause() external pure {
        revert PermanentlyUnpaused();
    }

    function mint(address recipient, uint256 amount) external onlyBaal {
        if (recipient == address(0)) revert ZeroAddress();
        totalSupply += amount;
        balanceOf[recipient] += amount;
        emit Transfer(address(0), recipient, amount);
    }

    function burn(address account, uint256 amount) external onlyBaal {
        uint256 available = balanceOf[account];
        if (available < amount) revert InsufficientBalance(account, available, amount);
        unchecked {
            balanceOf[account] = available - amount;
            totalSupply -= amount;
        }
        emit Transfer(account, address(0), amount);
    }

    function transfer(address recipient, uint256 amount) external returns (bool) {
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        if (spender == address(0)) revert ZeroAddress();
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        uint256 available = allowance[sender][msg.sender];
        if (available != type(uint256).max) {
            if (available < amount) revert InsufficientAllowance(sender, msg.sender, available, amount);
            unchecked {
                allowance[sender][msg.sender] = available - amount;
            }
        }
        _transfer(sender, recipient, amount);
        return true;
    }

    function _transfer(address sender, address recipient, uint256 amount) internal {
        if (sender == address(0) || recipient == address(0)) revert ZeroAddress();
        uint256 available = balanceOf[sender];
        if (available < amount) revert InsufficientBalance(sender, available, amount);
        unchecked {
            balanceOf[sender] = available - amount;
            balanceOf[recipient] += amount;
        }
        emit Transfer(sender, recipient, amount);
    }
}
"
    },
    "contracts/MockDex.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20Minimal} from "./Interfaces.sol";

/// @notice Mirror-only constant-price venue: swap settlement (USDC-mock) <-> a mock asset at `price`.
/// @dev Both tokens are 6-decimal TestTokens; `price` is settlement units per one whole asset unit
/// (PRICE_UNIT = 1e6, so price 2_000_000 means 2 USDC per MOCK). Anyone may move the price: the
/// mirror uses that to drive a Strategy's take-profit / stop-loss rules. Liquidity is whatever was
/// transferred in. Never deployed anywhere but a local anvil; real venues are named in the
/// Strategy parameters on mainnet.
contract MockDex {
    uint256 public constant PRICE_UNIT = 1e6;

    IERC20Minimal public immutable settlement;
    IERC20Minimal public immutable asset;
    uint256 public price;

    error ZeroAddress();
    error ZeroPrice();
    error ZeroAmount();
    error TransferFailed();

    event PriceSet(uint256 price);
    event Drained(address indexed token, address indexed to, uint256 amount);
    event Bought(address indexed buyer, uint256 settlementIn, uint256 assetOut);
    event Sold(address indexed seller, uint256 assetIn, uint256 settlementOut);

    /// @param settlement_ Settlement token (USDC-mock).
    /// @param asset_ Traded asset (MOCK).
    /// @param price_ Initial price in settlement units per whole asset unit.
    constructor(IERC20Minimal settlement_, IERC20Minimal asset_, uint256 price_) {
        if (address(settlement_) == address(0) || address(asset_) == address(0)) revert ZeroAddress();
        if (price_ == 0) revert ZeroPrice();
        settlement = settlement_;
        asset = asset_;
        price = price_;
        emit PriceSet(price_);
    }

    /// @notice Move the price (mirror control; anyone).
    function setPrice(uint256 price_) external {
        if (price_ == 0) revert ZeroPrice();
        price = price_;
        emit PriceSet(price_);
    }

    /// @notice Remove the whole balance of `token` (mirror control; anyone): simulates a dead venue
    /// whose sells revert, so scenarios can show that stop()/migrate() never call it.
    /// @param token The token to drain (settlement or asset).
    /// @param to Recipient of the drained balance.
    /// @return amount Units moved.
    function drain(IERC20Minimal token, address to) external returns (uint256 amount) {
        amount = token.balanceOf(address(this));
        if (amount == 0) revert ZeroAmount();
        if (!token.transfer(to, amount)) revert TransferFailed();
        emit Drained(address(token), to, amount);
    }

    /// @notice Asset received for `settlementIn` at the current price.
    function quoteBuy(uint256 settlementIn) public view returns (uint256 assetOut) {
        return (settlementIn * PRICE_UNIT) / price;
    }

    /// @notice Settlement received for `assetIn` at the current price.
    function quoteSell(uint256 assetIn) public view returns (uint256 settlementOut) {
        return (assetIn * price) / PRICE_UNIT;
    }

    /// @notice Pull `settlementIn` (pre-approved) and send the asset at the current price.
    function buy(uint256 settlementIn) external returns (uint256 assetOut) {
        if (settlementIn == 0) revert ZeroAmount();
        assetOut = quoteBuy(settlementIn);
        if (assetOut == 0) revert ZeroAmount();
        if (!settlement.transferFrom(msg.sender, address(this), settlementIn)) revert TransferFailed();
        if (!asset.transfer(msg.sender, assetOut)) revert TransferFailed();
        emit Bought(msg.sender, settlementIn, assetOut);
    }

    /// @notice Pull `assetIn` (pre-approved) and send settlement at the current price.
    function sell(uint256 assetIn) external returns (uint256 settlementOut) {
        if (assetIn == 0) revert ZeroAmount();
        settlementOut = quoteSell(assetIn);
        if (settlementOut == 0) revert ZeroAmount();
        if (!asset.transferFrom(msg.sender, address(this), assetIn)) revert TransferFailed();
        if (!settlement.transfer(msg.sender, settlementOut)) revert TransferFailed();
        emit Sold(msg.sender, assetIn, settlementOut);
    }
}
"
