    "contracts/PaymentProposal.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ProposalBase} from "./ProposalBase.sol";

/// @notice Payment template (DESIGN.md §7.1): on start(), transfer the listed amounts of settlement
/// to the listed addresses, once; anything left over goes back to the Safe; then Complete.
/// @dev params = abi.encode(address[] recipients, uint256[] amounts); budget = sum(amounts).
/// The proposer has no operational role: the Safe funds and starts, the contract pays and ends.
contract PaymentProposal is ProposalBase {
    address[] private _recipients;
    uint256[] private _amounts;

    error LengthMismatch(uint256 recipients, uint256 amounts);
    error NoRecipients();
    error ZeroAmount(uint256 index);

    event Paid(address indexed recipient, uint256 amount);

    /// @param safe_ The treasury Safe.
    /// @param settlement_ The settlement ERC-20.
    /// @param operator_ The proposer (recorded; no role).
    /// @param recipients Payees.
    /// @param amounts Settlement units per payee (same length).
    constructor(address safe_, address settlement_, address operator_, address[] memory recipients, uint256[] memory amounts)
        ProposalBase(safe_, settlement_, operator_)
    {
        _set(recipients, amounts);
    }

    /// @inheritdoc ProposalBase
    function template() public pure override returns (string memory) {
        return "Payment";
    }

    /// @notice The payment list.
    function payments() external view returns (address[] memory recipients, uint256[] memory amounts) {
        return (_recipients, _amounts);
    }

    /// @dev Pay every recipient once, return the rest, end.
    function _start() internal override {
        uint256 balance = held();
        if (balance < budget) revert Underfunded(budget, balance);
        for (uint256 i; i < _recipients.length; ++i) {
            _transfer(_recipients[i], _amounts[i]);
            emit Paid(_recipients[i], _amounts[i]);
        }
        _complete();
    }

    /// @dev Only meaningful before start: the topped-up amount joins what start() checks and returns.
    function _topUp(uint256 amount) internal override {
        _requireStatus(Status.Pending);
        budget += amount;
    }

    /// @dev Replace the payment list before start.
    function _amend(bytes calldata params) internal override {
        _requireStatus(Status.Pending);
        (address[] memory recipients, uint256[] memory amounts) = abi.decode(params, (address[], uint256[]));
        delete _recipients;
        delete _amounts;
        _set(recipients, amounts);
    }

    function _set(address[] memory recipients, uint256[] memory amounts) private {
        if (recipients.length != amounts.length) revert LengthMismatch(recipients.length, amounts.length);
        if (recipients.length == 0) revert NoRecipients();
        uint256 total;
        for (uint256 i; i < recipients.length; ++i) {
            if (recipients[i] == address(0)) revert ZeroAddress();
            if (amounts[i] == 0) revert ZeroAmount(i);
            _recipients.push(recipients[i]);
            _amounts.push(amounts[i]);
            total += amounts[i];
        }
        budget = total;
        paramsHash = keccak256(abi.encode(recipients, amounts));
    }
}
"
    },
    "contracts/ProjectProposal.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ProposalBase} from "./ProposalBase.sol";

/// @notice Project template (DESIGN.md §7.3): a funding plan in tranches, each released to the
/// operator when its condition holds: a date, or confirmation by named verifiers (never the
/// operator). Unspent funds return to the Safe on stop(), on the deadline (end()), or when the
/// last tranche is released (Complete).
/// @dev params = abi.encode(Tranche[] tranches, uint256 deadline). Date tranches already due are
/// released inside start(), so "first tranche on vote" is releaseType Date with releaseAt 0.
/// topUp(amount) (Safe only) adds money without a schedule; amend(params) (Safe only) cancels every
/// unreleased tranche and installs the new list (released tranches are history and stay). Both are
/// normally voted in one multicall. Anything held beyond the unreleased tranches is unallocated and
/// returns with the rest.
contract ProjectProposal is ProposalBase {
    enum ReleaseType {
        Date,
        Verifiers
    }

    struct Tranche {
        uint256 amount;
        ReleaseType releaseType;
        uint256 releaseAt;
        address[] verifiers;
        uint16 threshold;
    }

    struct TrancheState {
        bool released;
        bool cancelled;
        uint16 confirmations;
    }

    Tranche[] private _tranches;
    TrancheState[] private _state;
    mapping(uint256 trancheId => mapping(address verifier => bool)) public isVerifier;
    mapping(uint256 trancheId => mapping(address verifier => bool)) public confirmedBy;

    uint256 public released;

    error NoTranches();
    error ZeroAmount(uint256 index);
    error DateTrancheHasVerifiers(uint256 index);
    error NoVerifiers(uint256 index);
    error VerifierIsOperator(uint256 index, address verifier);
    error DuplicateVerifier(uint256 index, address verifier);
    error InvalidThreshold(uint256 index, uint16 threshold, uint256 verifierCount);
    error UnknownTranche(uint256 index);
    error TrancheSettled(uint256 index);
    error WrongReleaseType(uint256 index);
    error NotDue(uint256 index, uint256 releaseAt);
    error OnlyVerifier(uint256 index, address caller);
    error AlreadyConfirmed(uint256 index, address verifier);
    error NoDeadline();
    error DeadlineNotReached(uint256 deadline);
    error Overcommitted(uint256 scheduled, uint256 held);

    event TrancheAdded(uint256 indexed index, uint256 amount, ReleaseType releaseType, uint256 releaseAt, address[] verifiers, uint16 threshold);
    event TrancheCancelled(uint256 indexed index);
    event TrancheConfirmed(uint256 indexed index, address indexed verifier, uint16 confirmations);
    event TrancheReleased(uint256 indexed index, address indexed operator, uint256 amount);

    /// @param safe_ The treasury Safe.
    /// @param settlement_ The settlement ERC-20.
    /// @param operator_ The proposer (receives tranches; can never verify).
    /// @param tranches The funding plan.
    /// @param deadline_ Unix time after which anyone may end the project (0 = none).
    constructor(address safe_, address settlement_, address operator_, Tranche[] memory tranches, uint256 deadline_)
        ProposalBase(safe_, settlement_, operator_)
    {
        uint256 total = _addTranches(tranches);
        budget = total;
        deadline = deadline_;
        paramsHash = keccak256(abi.encode(tranches, deadline_));
    }

    /// @inheritdoc ProposalBase
    function template() public pure override returns (string memory) {
        return "Project";
    }

    /// @notice Number of tranches ever scheduled (including released and cancelled).
    function trancheCount() external view returns (uint256) {
        return _tranches.length;
    }

    /// @notice One tranche and its state.
    function tranche(uint256 index) external view returns (Tranche memory plan, TrancheState memory state) {
        if (index >= _tranches.length) revert UnknownTranche(index);
        return (_tranches[index], _state[index]);
    }

    /// @notice Sum of tranches neither released nor cancelled.
    function unreleased() public view returns (uint256 total) {
        for (uint256 i; i < _tranches.length; ++i) {
            if (!_state[i].released && !_state[i].cancelled) total += _tranches[i].amount;
        }
    }

    /// @notice Release a Date tranche whose date has come; anyone may call.
    function release(uint256 index) external nonReentrant {
        _requireStatus(Status.Running);
        Tranche storage plan = _open(index);
        if (plan.releaseType != ReleaseType.Date) revert WrongReleaseType(index);
        if (block.timestamp < plan.releaseAt) revert NotDue(index, plan.releaseAt);
        _release(index);
    }

    /// @notice Confirm a Verifiers tranche; at threshold it is released to the operator.
    function confirm(uint256 index) external nonReentrant {
        _requireStatus(Status.Running);
        Tranche storage plan = _open(index);
        if (plan.releaseType != ReleaseType.Verifiers) revert WrongReleaseType(index);
        if (!isVerifier[index][msg.sender]) revert OnlyVerifier(index, msg.sender);
        if (confirmedBy[index][msg.sender]) revert AlreadyConfirmed(index, msg.sender);
        confirmedBy[index][msg.sender] = true;
        uint16 count = _state[index].confirmations + 1;
        _state[index].confirmations = count;
        emit TrancheConfirmed(index, msg.sender, count);
        if (count >= plan.threshold) _release(index);
    }

    /// @notice After the deadline anyone may end the project; unreleased tranches return to the Safe.
    function end() external nonReentrant {
        _requireStatus(Status.Running);
        if (deadline == 0) revert NoDeadline();
        if (block.timestamp < deadline) revert DeadlineNotReached(deadline);
        _complete();
    }

    /// @dev Funding check, then release every Date tranche already due.
    function _start() internal override {
        uint256 balance = held();
        if (balance < budget) revert Underfunded(budget, balance);
        for (uint256 i; i < _tranches.length && status == Status.Running; ++i) {
            TrancheState storage state = _state[i];
            if (state.released || state.cancelled) continue;
            Tranche storage plan = _tranches[i];
            if (plan.releaseType == ReleaseType.Date && block.timestamp >= plan.releaseAt) _release(i);
        }
    }

    /// @dev Record more money; it is unallocated until amend() schedules it.
    function _topUp(uint256 amount) internal override {
        budget += amount;
        uint256 balance = held();
        if (balance + released < budget) revert Underfunded(budget - released, balance);
    }

    /// @dev Cancel every unreleased tranche and install the new plan (must fit what is held).
    function _amend(bytes calldata params) internal override {
        (Tranche[] memory tranches, uint256 deadline_) = abi.decode(params, (Tranche[], uint256));
        for (uint256 i; i < _tranches.length; ++i) {
            TrancheState storage state = _state[i];
            if (state.released || state.cancelled) continue;
            state.cancelled = true;
            emit TrancheCancelled(i);
        }
        uint256 scheduled = _addTranches(tranches);
        uint256 balance = held();
        if (scheduled > balance) revert Overcommitted(scheduled, balance);
        deadline = deadline_;
        paramsHash = keccak256(params);
        if (status == Status.Running) _releaseDue();
    }

    /// @dev Release every Date tranche already due (used after amend while Running).
    function _releaseDue() private {
        for (uint256 i; i < _tranches.length && status == Status.Running; ++i) {
            TrancheState storage state = _state[i];
            if (state.released || state.cancelled) continue;
            Tranche storage plan = _tranches[i];
            if (plan.releaseType == ReleaseType.Date && block.timestamp >= plan.releaseAt) _release(i);
        }
    }

    /// @dev Pay one tranche to the operator; Complete when nothing is left to release.
    function _release(uint256 index) private {
        TrancheState storage state = _state[index];
        state.released = true;
        uint256 amount = _tranches[index].amount;
        released += amount;
        _transfer(operator, amount);
        emit TrancheReleased(index, operator, amount);
        if (unreleased() == 0) _complete();
    }

    /// @dev Validate and append tranches; returns their sum.
    function _addTranches(Tranche[] memory tranches) private returns (uint256 total) {
        if (tranches.length == 0) revert NoTranches();
        for (uint256 i; i < tranches.length; ++i) {
            Tranche memory plan = tranches[i];
            uint256 index = _tranches.length;
            if (plan.amount == 0) revert ZeroAmount(index);
            if (plan.releaseType == ReleaseType.Date) {
                if (plan.verifiers.length != 0 || plan.threshold != 0) revert DateTrancheHasVerifiers(index);
            } else {
                if (plan.verifiers.length == 0) revert NoVerifiers(index);
                if (plan.threshold == 0 || plan.threshold > plan.verifiers.length) {
                    revert InvalidThreshold(index, plan.threshold, plan.verifiers.length);
                }
            }
            Tranche storage stored = _tranches.push();
            stored.amount = plan.amount;
            stored.releaseType = plan.releaseType;
            stored.releaseAt = plan.releaseAt;
            stored.threshold = plan.threshold;
            for (uint256 j; j < plan.verifiers.length; ++j) {
                address verifier = plan.verifiers[j];
                if (verifier == address(0)) revert ZeroAddress();
                if (verifier == operator) revert VerifierIsOperator(index, verifier);
                if (isVerifier[index][verifier]) revert DuplicateVerifier(index, verifier);
                isVerifier[index][verifier] = true;
                stored.verifiers.push(verifier);
            }
            _state.push(TrancheState({released: false, cancelled: false, confirmations: 0}));
            total += plan.amount;
            emit TrancheAdded(index, plan.amount, plan.releaseType, plan.releaseAt, plan.verifiers, plan.threshold);
        }
    }

    /// @dev The tranche at `index`, which must exist and be neither released nor cancelled.
    function _open(uint256 index) private view returns (Tranche storage plan) {
        if (index >= _tranches.length) revert UnknownTranche(index);
        TrancheState storage state = _state[index];
        if (state.released || state.cancelled) revert TrancheSettled(index);
        return _tranches[index];
    }
}
"
    },
    "contracts/StrategyProposal.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20Minimal} from "./Interfaces.sol";
import {ProposalBase} from "./ProposalBase.sol";

/// @notice Minimal venue surface a Strategy trades on (the mirror's MockDex implements it).
interface IStrategyVenue {
    function price() external view returns (uint256);
    function buy(uint256 settlementIn) external returns (uint256 assetOut);
    function sell(uint256 assetIn) external returns (uint256 settlementOut);
}

/// @notice Strategy template (DESIGN.md §7.2): holds a settlement budget and trades it against one
/// asset on one venue by a coded rule. `run()` is callable by anyone (no keeper can hold it hostage).
/// @dev The coded rule, evaluated per run():
///   1. deadline reached -> unwind (sell all asset) and return every settlement unit to the Safe; Complete.
///   2. otherwise at most one run per `minInterval` seconds;
///   3. value = settlement held + asset held x venue price; if takeProfitBps != 0 and
///      value >= budget x (1 + takeProfit) or stopLossBps != 0 and value <= budget x (1 - stopLoss)
///      -> unwind, return, Complete;
///   4. otherwise buy the asset with min(maxPerRun, settlement held) settlement units.
/// stop() and migrate(newContract) (Safe only) move the raw holdings (every settlement unit and every
/// asset unit) to the Safe / the new contract WITHOUT calling the venue, so a dead venue can never trap
/// funds (DESIGN.md §7; decision.md phase 2a ruling 2). Unwinding on the venue is run()'s job before the
/// deadline. params = abi.encode(address venue, address asset, uint256 budget, Rule rule);
/// amend(params) replaces the Rule only (venue, asset and budget do not change by amend).
contract StrategyProposal is ProposalBase {
    struct Rule {
        uint256 maxPerRun;
        uint256 minInterval;
        uint256 deadline;
        uint256 takeProfitBps;
        uint256 stopLossBps;
    }

    uint256 public constant PRICE_UNIT = 1e6;
    uint256 public constant BPS = 10_000;

    IStrategyVenue public immutable venue;
    IERC20Minimal public immutable asset;

    Rule public rule;
    uint256 public lastRun;
    uint256 public runs;

    error ZeroBudget();
    error ZeroMaxPerRun();
    error DeadlinePassed(uint256 deadline, uint256 nowTs);
    error BadBps(uint256 bps);
    error TooSoon(uint256 nextRunAt);
    error NothingToDo();
    error ApproveFailed();

    event Ran(uint256 indexed run, uint256 valueBefore, uint256 bought, uint256 assetOut);
    event Unwound(uint256 assetIn, uint256 settlementOut, string reason);
    event Moved(address indexed to, uint256 settlementMoved, uint256 assetMoved, string reason);

    /// @param safe_ The treasury Safe.
    /// @param settlement_ The settlement ERC-20.
    /// @param operator_ The proposer (leads by default; has no special power).
    /// @param venue_ The venue (mirror: MockDex).
    /// @param asset_ The traded asset.
    /// @param budget_ Settlement units the Safe funds on start.
    /// @param rule_ The coded rule's parameters.
    constructor(
        address safe_,
        address settlement_,
        address operator_,
        address venue_,
        address asset_,
        uint256 budget_,
        Rule memory rule_
    ) ProposalBase(safe_, settlement_, operator_) {
        if (venue_ == address(0) || asset_ == address(0)) revert ZeroAddress();
        if (budget_ == 0) revert ZeroBudget();
        venue = IStrategyVenue(venue_);
        asset = IERC20Minimal(asset_);
        budget = budget_;
        _setRule(rule_);
        paramsHash = keccak256(abi.encode(venue_, asset_, budget_, rule_));
    }

    /// @inheritdoc ProposalBase
    function template() public pure override returns (string memory) {
        return "Strategy";
    }

    /// @notice Settlement held + asset held valued at the venue price.
    function value() public view returns (uint256) {
        return held() + (asset.balanceOf(address(this)) * venue.price()) / PRICE_UNIT;
    }

    /// @notice Execute one step of the coded rule; anyone may call.
    function run() external nonReentrant {
        _requireStatus(Status.Running);
        if (block.timestamp >= rule.deadline) {
            _unwind("deadline");
            _complete();
            return;
        }
        uint256 nextRunAt = lastRun + rule.minInterval;
        if (runs != 0 && block.timestamp < nextRunAt) revert TooSoon(nextRunAt);
        lastRun = block.timestamp;
        runs += 1;

        uint256 valueBefore = value();
        if (rule.takeProfitBps != 0 && valueBefore >= (budget * (BPS + rule.takeProfitBps)) / BPS) {
            _unwind("take-profit");
            _complete();
            return;
        }
        if (rule.stopLossBps != 0 && valueBefore <= (budget * (BPS - rule.stopLossBps)) / BPS) {
            _unwind("stop-loss");
            _complete();
            return;
        }

        uint256 balance = held();
        uint256 size = balance < rule.maxPerRun ? balance : rule.maxPerRun;
        if (size == 0) revert NothingToDo();
        if (!settlement.approve(address(venue), size)) revert ApproveFailed();
        uint256 assetOut = venue.buy(size);
        emit Ran(runs, valueBefore, size, assetOut);
    }

    /// @dev Funding check only; the rule runs through run(). A migrated position arrives as raw
    /// holdings (settlement plus asset), so the settlement-only check applies when no asset is held;
    /// valuing the asset here would call the venue, which stop()/migrate() must never depend on.
    function _start() internal view override {
        uint256 balance = held();
        if (balance < budget && asset.balanceOf(address(this)) == 0) revert Underfunded(budget, balance);
    }

    /// @dev Replace the rule; venue, asset and budget stay.
    function _amend(bytes calldata params) internal override {
        Rule memory next = abi.decode(params, (Rule));
        _setRule(next);
        paramsHash = keccak256(abi.encode(address(venue), address(asset), budget, next));
    }

    /// @dev Move the raw holdings (settlement + asset) to the Safe; the venue is not called.
    function _stop() internal override returns (uint256 returned) {
        return _moveHoldings(safe, "stop");
    }

    /// @dev Move the raw holdings (settlement + asset) to the new voted contract; the venue is not called.
    function _migrate(address newContract) internal override returns (uint256 moved) {
        return _moveHoldings(newContract, "migrate");
    }

    /// @dev Transfer every settlement unit and every asset unit held to `to` without touching the venue.
    /// @return settlementMoved Settlement units transferred (the asset amount is in the Moved event).
    function _moveHoldings(address to, string memory reason) private returns (uint256 settlementMoved) {
        settlementMoved = _returnSettlement(to);
        uint256 assetBalance = asset.balanceOf(address(this));
        if (assetBalance != 0 && !asset.transfer(to, assetBalance)) revert TransferFailed();
        emit Moved(to, settlementMoved, assetBalance, reason);
    }

    function _setRule(Rule memory next) private {
        if (next.maxPerRun == 0) revert ZeroMaxPerRun();
        if (next.deadline <= block.timestamp) revert DeadlinePassed(next.deadline, block.timestamp);
        if (next.takeProfitBps > BPS * 100) revert BadBps(next.takeProfitBps);
        if (next.stopLossBps >= BPS) revert BadBps(next.stopLossBps);
        rule = next;
        deadline = next.deadline;
    }

    /// @dev Sell every asset unit held back into settlement.
    function _unwind(string memory reason) private {
        uint256 assetBalance = asset.balanceOf(address(this));
        if (assetBalance == 0) return;
        if (!asset.approve(address(venue), assetBalance)) revert ApproveFailed();
        uint256 settlementOut = venue.sell(assetBalance);
        emit Unwound(assetBalance, settlementOut, reason);
    }
}
"
    },
    "contracts/TemplateFactory.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Create2} from "@openzeppelin/contracts/utils/Create2.sol";

import {IBaalV3, IERC20Minimal} from "./Interfaces.sol";
import {IProposalContract} from "./IProposalContract.sol";
import {ConfigProposal} from "./ConfigProposal.sol";
import {PaymentProposal} from "./PaymentProposal.sol";
import {ProjectProposal} from "./ProjectProposal.sol";
import {StrategyProposal} from "./StrategyProposal.sol";

/// @notice One CREATE2 deployer per template. The instance address is a pure function of
/// (deployer, salt, template creation code, safe, settlement, member, params): nobody, the relay
/// included, can put different code at the address a member signed for (decision.md phase 2b ruling 2).
interface ITemplateDeployer {
    /// @notice Template name ("Payment", "Strategy", "Project", "Config").
    function template() external pure returns (string memory);

    /// @notice The exact creation code + constructor arguments an instance is created from.
    function initCode(address member, bytes calldata params) external view returns (bytes memory);

    /// @notice The CREATE2 address of the instance for (member, params, salt).
    function predict(address member, bytes calldata params, bytes32 salt) external view returns (address);

    /// @notice Deploy the instance at `predict(member, params, salt)`; reverts if that address has code.
    function deploy(address member, bytes calldata params, bytes32 salt) external returns (address);
}

/// @dev Shared CREATE2 plumbing; each concrete deployer supplies the template's init code.
abstract contract TemplateDeployer is ITemplateDeployer {
    address public immutable safe;
    address public immutable settlement;

    error ZeroAddress();

    /// @param safe_ The treasury Safe (owner of every instance).
    /// @param settlement_ The settlement ERC-20 (USDC).
    constructor(address safe_, address settlement_) {
        if (safe_ == address(0) || settlement_ == address(0)) revert ZeroAddress();
        safe = safe_;
        settlement = settlement_;
    }

    /// @inheritdoc ITemplateDeployer
    function initCode(address member, bytes calldata params) public view virtual returns (bytes memory);

    /// @inheritdoc ITemplateDeployer
    function predict(address member, bytes calldata params, bytes32 salt) external view returns (address) {
        return Create2.computeAddress(salt, keccak256(initCode(member, params)), address(this));
    }

    /// @inheritdoc ITemplateDeployer
    /// @dev CREATE2 in assembly so a constructor revert (e.g. a template's ZeroAmount) bubbles up
    /// with its own data instead of a generic "failed on deploy".
    function deploy(address member, bytes calldata params, bytes32 salt) external returns (address instance) {
        bytes memory code = initCode(member, params);
        assembly ("memory-safe") {
            instance := create2(0, add(code, 0x20), mload(code), salt)
            if iszero(instance) {
                let size := returndatasize()
                returndatacopy(0, 0, size)
                revert(0, size)
            }
        }
    }
}

/// @notice CREATE2 deployer of PaymentProposal; params = abi.encode(address[] recipients, uint256[] amounts).
contract PaymentDeployer is TemplateDeployer {
    constructor(address safe_, address settlement_) TemplateDeployer(safe_, settlement_) {}

    /// @inheritdoc ITemplateDeployer
    function template() external pure returns (string memory) {
        return "Payment";
    }

    /// @inheritdoc ITemplateDeployer
    function initCode(address member, bytes calldata params) public view override returns (bytes memory) {
        (address[] memory recipients, uint256[] memory amounts) = abi.decode(params, (address[], uint256[]));
        return abi.encodePacked(type(PaymentProposal).creationCode, abi.encode(safe, settlement, member, recipients, amounts));
    }
}

/// @notice CREATE2 deployer of StrategyProposal; params = abi.encode(address venue, address asset, uint256 budget, Rule rule).
contract StrategyDeployer is TemplateDeployer {
    constructor(address safe_, address settlement_) TemplateDeployer(safe_, settlement_) {}

    /// @inheritdoc ITemplateDeployer
    function template() external pure returns (string memory) {
        return "Strategy";
    }

    /// @inheritdoc ITemplateDeployer
    function initCode(address member, bytes calldata params) public view override returns (bytes memory) {
        (address venue, address asset, uint256 budget, StrategyProposal.Rule memory rule) =
            abi.decode(params, (address, address, uint256, StrategyProposal.Rule));
        return abi.encodePacked(type(StrategyProposal).creationCode, abi.encode(safe, settlement, member, venue, asset, budget, rule));
    }
}

/// @notice CREATE2 deployer of ProjectProposal; params = abi.encode(Tranche[] tranches, uint256 deadline).
contract ProjectDeployer is TemplateDeployer {
    constructor(address safe_, address settlement_) TemplateDeployer(safe_, settlement_) {}

    /// @inheritdoc ITemplateDeployer
    function template() external pure returns (string memory) {
        return "Project";
    }

    /// @inheritdoc ITemplateDeployer
    function initCode(address member, bytes calldata params) public view override returns (bytes memory) {
        (ProjectProposal.Tranche[] memory tranches, uint256 deadline) = abi.decode(params, (ProjectProposal.Tranche[], uint256));
        return abi.encodePacked(type(ProjectProposal).creationCode, abi.encode(safe, settlement, member, tranches, deadline));
    }
}

/// @notice CREATE2 deployer of ConfigProposal; params = abi.encode(Config config).
contract ConfigDeployer is TemplateDeployer {
    IBaalV3 public immutable baal;

    /// @param baal_ The Baal whose governance parameters a Config instance verifies.
    constructor(address safe_, address settlement_, IBaalV3 baal_) TemplateDeployer(safe_, settlement_) {
        if (address(baal_) == address(0)) revert ZeroAddress();
        baal = baal_;
    }

    /// @inheritdoc ITemplateDeployer
    function template() external pure returns (string memory) {
        return "Config";
    }

    /// @inheritdoc ITemplateDeployer
    function initCode(address member, bytes calldata params) public view override returns (bytes memory) {
        ConfigProposal.Config memory config = abi.decode(params, (ConfigProposal.Config));
        return abi.encodePacked(type(ConfigProposal).creationCode, abi.encode(safe, settlement, member, baal, config));
    }
}

/// @notice The template factory agents and the intent account use (decision.md phase 2b rulings 2, 3):
/// `deploy` puts the template instance for (template, params, member, salt) at its deterministic
/// address (idempotent: an existing instance is returned, never redeployed), and `proposalData`
/// builds the exact Baal multicall that funds and starts that instance, so a member signs only the
/// template id, the parameters and a salt, and the account derives everything else on-chain.
/// @dev Template ids: 0 Payment, 1 Strategy, 2 Project, 3 Config. Permissionless by design: whoever
/// deploys, the code and the operator (`member`) are fixed by the arguments. The relay sponsors
/// deployments only for members holding >= sponsorThreshold (relay policy, not code).
contract TemplateFactory {
    address public immutable safe;
    IERC20Minimal public immutable settlement;
    IBaalV3 public immutable baal;
    ITemplateDeployer public immutable paymentDeployer;
    ITemplateDeployer public immutable strategyDeployer;
    ITemplateDeployer public immutable projectDeployer;
    ITemplateDeployer public immutable configDeployer;

    /// @dev Gnosis MultiSend.multiSend(bytes) selector; Baal executes proposalData through MultiSend.
    bytes4 private constant MULTISEND = 0x8d80ff0a;
    uint8 public constant TEMPLATE_COUNT = 4;

    error ZeroAddress();
    error UnknownTemplate(uint8 template);
    error DeployerMismatch(address deployer, string expected);
    error AddressMismatch(address predicted, address deployed);

    event InstanceDeployed(
        uint8 indexed template, address indexed instance, address indexed member, bytes32 paramsHash, bytes32 salt, bytes32 codeHash
    );

    /// @param safe_ The treasury Safe.
    /// @param settlement_ The settlement ERC-20 (USDC).
    /// @param baal_ The DAO's Baal.
    /// @param deployers_ [Payment, Strategy, Project, Config] deployers bound to the same Safe and settlement.
    constructor(address safe_, address settlement_, IBaalV3 baal_, ITemplateDeployer[4] memory deployers_) {
        if (safe_ == address(0) || settlement_ == address(0) || address(baal_) == address(0)) revert ZeroAddress();
        safe = safe_;
        settlement = IERC20Minimal(settlement_);
        baal = baal_;
        string[4] memory names = ["Payment", "Strategy", "Project", "Config"];
        for (uint256 i; i < 4; ++i) {
            ITemplateDeployer deployer_ = deployers_[i];
            if (address(deployer_) == address(0)) revert ZeroAddress();
            if (keccak256(bytes(deployer_.template())) != keccak256(bytes(names[i]))) revert DeployerMismatch(address(deployer_), names[i]);
        }
        paymentDeployer = deployers_[0];
        strategyDeployer = deployers_[1];
        projectDeployer = deployers_[2];
        configDeployer = deployers_[3];
    }

    /// @notice Deployer of a template id.
    function deployer(uint8 template) public view returns (ITemplateDeployer) {
        if (template == 0) return paymentDeployer;
        if (template == 1) return strategyDeployer;
        if (template == 2) return projectDeployer;
        if (template == 3) return configDeployer;
        revert UnknownTemplate(template);
    }

    /// @notice Template name of a template id.
    function templateName(uint8 template) external view returns (string memory) {
        return deployer(template).template();
    }

    /// @notice The instance address for (template, params, member, salt), deployed or not.
    function predict(uint8 template, bytes calldata params, address member, bytes32 salt) public view returns (address) {
        return deployer(template).predict(member, params, salt);
    }

    /// @notice Deploy the instance if absent; returns its address and runtime code hash either way.
    /// @param template Template id.
    /// @param params abi.encode(params) exactly as the template hashes into `paramsHash`.
    /// @param member The proposer; becomes the instance's `operator`.
    /// @param salt Distinguishes otherwise identical proposals (the relay uses the member's intent nonce).
    /// @return instance The deterministic instance address.
    /// @return codeHash keccak256 of the runtime code at `instance` (immutables included).
    function deploy(uint8 template, bytes calldata params, address member, bytes32 salt) public returns (address instance, bytes32 codeHash) {
        if (member == address(0)) revert ZeroAddress();
        ITemplateDeployer d = deployer(template);
        instance = d.predict(member, params, salt);
        if (instance.code.length == 0) {
            address deployed = d.deploy(member, params, salt);
            if (deployed != instance) revert AddressMismatch(instance, deployed);
            codeHash = instance.codehash;
            emit InstanceDeployed(template, instance, member, keccak256(params), salt, codeHash);
        } else {
            codeHash = instance.codehash;
        }
    }

    /// @notice The exact Baal proposalData (MultiSend calldata) that funds and starts `instance`:
    /// `[settlement.transfer(instance, budget), instance.start()]`, the transfer omitted when budget
    /// is 0; for Config `[baal.setGovernanceConfig(params), instance.start()]` (docs/TEMPLATES.md).
    /// @param template Template id.
    /// @param params The instance's params bytes (used by Config).
    /// @param instance A deployed instance.
    function proposalData(uint8 template, bytes calldata params, address instance) public view returns (bytes memory) {
        bytes memory packed;
        if (template == 3) {
            packed = _pack(address(baal), abi.encodeWithSelector(IBaalV3.setGovernanceConfig.selector, params));
        } else {
            (,,, uint256 budget,,) = IProposalContract(instance).describe();
            if (budget != 0) packed = _pack(address(settlement), abi.encodeWithSelector(IERC20Minimal.transfer.selector, instance, budget));
        }
        packed = abi.encodePacked(packed, _pack(instance, abi.encodeWithSelector(IProposalContract.start.selector)));
        return abi.encodeWithSelector(MULTISEND, packed);
    }

    /// @notice Dry run for agents (call with eth_call): deploy if absent and describe the result.
    /// @return instance The instance address.
    /// @return codeHash keccak256 of its runtime code.
    /// @return paramsHash keccak256(params) as the instance reports it.
    /// @return budget Settlement the Safe will transfer on pass.
    /// @return deadline The instance's deadline (0 = none).
    /// @return data The proposalData the account will submit.
    function quote(uint8 template, bytes calldata params, address member, bytes32 salt)
        external
        returns (address instance, bytes32 codeHash, bytes32 paramsHash, uint256 budget, uint256 deadline, bytes memory data)
    {
        (instance, codeHash) = deploy(template, params, member, salt);
        (, paramsHash,, budget, deadline,) = IProposalContract(instance).describe();
        data = proposalData(template, params, instance);
    }

    /// @dev One MultiSend transaction: operation 0 | to | value 0 | data length | data.
    function _pack(address to, bytes memory data) private pure returns (bytes memory) {
        return abi.encodePacked(uint8(0), to, uint256(0), data.length, data);
    }
}
"
    },
